 11	public class CheckoutService {
 12	    private static final Pattern ZIP_CODE_PATTERN = Pattern.compile("^\\d{8}$");
 13	    private static final double MAX_COURIER_WEIGHT = 5.0;
 14	    private static final double MAX_DISCOUNT_PERCENTAGE = 0.30;
 15	    private static final long PAYMENT_TIMEOUT_MS = 48 * 60 * 60 * 1000;
