189	    private static ValidationError validatePaymentMethod(CheckoutRequest req) throws SQLException {
190	        if (req.paymentMethod.equals("BANK_SLIP")) {
191	            OrderSummary summary = calculateSummary(req);
192	            if (summary.finalTotal > 1000.0) {
193	                return new ValidationError("PAYMENT_METHOD_UNAVAILABLE", 422);
194	            }
195	        }
196	        return null;
197	    }
