388	    private static TranslogResponse queryTranslog(String baseUrl, String zipCode, int weightGrams, String service) {
389	        try {
390	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", baseUrl, zipCode, weightGrams, service);
391	            java.net.HttpURLConnection conn = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
392	            conn.setRequestMethod("GET");
393	            conn.setConnectTimeout(2000);
394	            conn.setReadTimeout(2000);
395	
396	            int status = conn.getResponseCode();
397	            if (status != 200) {
398	                return null;
399	            }
400	
401	            String response = new String(conn.getInputStream().readAllBytes());
402	            com.google.gson.JsonElement element = com.google.gson.JsonParser.parseString(response);
403	            com.google.gson.JsonObject obj = element.getAsJsonObject();
404	
405	            if (obj.has("error")) {
406	                TranslogResponse resp = new TranslogResponse();
407	                resp.error = obj.get("error").getAsString();
408	                return resp;
409	            }
410	
411	            TranslogResponse resp = new TranslogResponse();
412	            resp.priceCents = obj.get("price_cents").getAsInt();
413	            resp.etaHours = obj.get("eta_hours").getAsInt();
414	            return resp;
415	        } catch (Exception e) {
416	            return null;
417	        }
418	    }
