420	    private static double calculateInsurance(CheckoutRequest req, double subtotal) {
421	        Enums.Region region = Enums.Region.valueOf(req.region);
422	        double percentage = 0;
423	        double limit = Double.MAX_VALUE;
424	
425	        switch (region) {
426	            case SOUTHEAST, SOUTH -> percentage = 0.01;
427	            case MIDWEST -> percentage = 0.015;
428	            case NORTH -> {
429	                percentage = 0.025;
430	                limit = 30.0;
431	            }
432	            case NORTHEAST -> {
433	                percentage = 0.02;
434	                limit = 30.0;
435	            }
436	        }
437	
438	        double insurance = MoneyUtils.round(subtotal * percentage);
439	        if (insurance > limit) {
440	            insurance = limit;
441	        }
442	        return insurance;
443	    }
